import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as Textarea from "../../ui/shadcn-textarea";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

export const view = Submodel.defineView<Model, Message>((): Html => {
  const h = html<Message>();

  return Textarea.view<Message>({
    id: "textarea-disabled",
    value: "",
    rows: 4,
    placeholder: "Type your message here.",
    isDisabled: true,
    toView: (attributes) =>
      h.div(
        [
          h.DataAttribute("disabled", ""),
          h.Class(Textarea.shadcnTextareaFieldClassName),
        ],
        [
          h.label(
            [
              ...attributes.label,
              h.Class(Textarea.shadcnTextareaLabelClassName),
            ],
            ["Message"]
          ),
          h.textarea(
            [...attributes.textarea, h.Class(Textarea.shadcnTextareaClassName)],
            []
          ),
        ]
      ),
  });
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("Shadcn Textarea Disabled example", () => {
  test("renders the origin disabled textarea demo", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(Scene.text("Message")).toExist(),
      Scene.expect(Scene.placeholder("Type your message here.")).toBeDisabled()
    );
  });
});
